import json

# Parse episodes.jsonl for model distribution
episodes_file = "/home/ubuntu/.agent-ml-research-be-idea-gen-0519-4/projects/policy_ambiguity_safety/artifacts/plan_010/episodes.jsonl"
models = {}
conditions = {}

with open(episodes_file, 'r') as f:
    for line in f:
        episode = json.loads(line)
        model = episode.get('model')
        condition = episode.get('condition')

        if model:
            models[model] = models.get(model, 0) + 1
        if condition:
            conditions[condition] = conditions.get(condition, 0) + 1

print("Model Distribution (Episodes):")
for model, count in sorted(models.items()):
    print(f"  {model}: {count}")

print("\nCondition Distribution (Episodes):")
for condition, count in sorted(conditions.items()):
    print(f"  {condition}: {count}")
